package org.sleepwell.app;
import android.content.*;import android.provider.CalendarContract;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import java.time.ZoneId;import java.util.*;import static org.junit.Assert.*;
public final class CalendarEventExportTest {
    @Test public void savedEffectivePeriodProducesFreshScalarIntentWithoutPrivateNotesOrAuthority()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();String database="calendar-event-"+UUID.randomUUID()+".db";try(Store store=new Store(c,database)){RecordDraft record=new RecordDraft(1700000000000L,1700028800000L);record.note="PRIVATE JOURNAL";record.awake.add(new RecordIntervals.Span(record.start,record.start+3600000));long id=Records.create(store,record,ZoneId.of("Asia/Riyadh"),System.currentTimeMillis());String before=BackupFingerprint.read(store);CalendarEventDraft draft=CalendarEventExport.draft(Records.get(store,id));Intent intent=CalendarEventExport.intent(draft,false);assertEquals(Intent.ACTION_INSERT,intent.getAction());assertEquals(CalendarContract.Events.CONTENT_URI,intent.getData());assertEquals(record.start,intent.getLongExtra(CalendarContract.EXTRA_EVENT_BEGIN_TIME,0));assertEquals(record.end,intent.getLongExtra(CalendarContract.EXTRA_EVENT_END_TIME,0));assertEquals(7*3600000L,draft.duration);assertEquals("Asia/Riyadh",intent.getStringExtra(CalendarContract.Events.EVENT_TIMEZONE));assertFalse(intent.getStringExtra(CalendarContract.Events.DESCRIPTION).contains(record.note));assertTrue(CalendarEventExport.intent(draft,true).getStringExtra(CalendarContract.Events.DESCRIPTION).contains(record.note));assertNull(intent.getClipData());assertNull(intent.getComponent());assertEquals(0,intent.getFlags());assertFalse(intent.hasExtra("record"));assertFalse(c.getPackageManager().getActivityInfo(new ComponentName(c,CalendarEventExportActivity.class),0).exported);assertEquals(before,BackupFingerprint.read(store));}finally{assertTrue(c.deleteDatabase(database));}}
}
